bool FirstTextIsNotEmpty(
  const std::vector<std::wstring>& texts
) {
  for (const std::wstring& text : texts) {
    return common::LenStr(text) > 0;
  }
  return true;
}

bool NoNumberIsZero(
  const std::vector<int64_t>& numbers
) {
  for (int64_t number : numbers) {
    switch (number) {
      case 0:
        return false;
    }
  }
  return true;
}

bool NoNumberIsMinusOne(
  const std::vector<int64_t>& numbers
) {
  for (size_t i = 0; i < numbers.size(); ++i) {
    int64_t number = numbers.at(i);
    switch (number) {
      case -1:
        return false;
    }
  }
  return true;
}

bool NoNumberAfterTheFirstIsOne(
  const std::vector<int64_t>& numbers
) {
  for (size_t i = 1; i < numbers.size(); ++i) {
    switch (numbers.at(i)) {
      case 1:
        return false;
    }
  }
  return true;
}

bool SumIsSmall(
  const std::vector<int64_t>& numbers
) {
  int64_t total = 0;
  for (int64_t number : numbers) {
    total = total + number;
  }
  return total < 100;
}

bool NoItemHasAnEmptyText(
  const std::vector<
    std::shared_ptr<types::IItem>
  >& items
) {
  for (const std::shared_ptr<types::IItem>& item : items) {
    auto texts = item->texts();
    for (const std::wstring& text : texts) {
      if (text == L"") {
        return false;
      }
    }
  }
  return true;
}

bool IsNeitherThirteenNorUnlucky(
  const std::vector<std::wstring>& texts
) {
  for (const std::wstring& x : texts) {
    if (x == L"thirteen") {
      return false;
    }
  }
  for (const std::wstring& x : texts) {
    if (x == L"unlucky") {
      return false;
    }
  }
  return true;
}

bool AlphaHasNoNegativeNumbers(
  types::Kind kind,
  const std::vector<int64_t>& numbers
) {
  switch (kind) {
    case types::Kind::kAlpha:
      for (int64_t number : numbers) {
        switch (number) {
          case -2:
            return false;
        }
      }
      break;
    default:
      break;
  }
  return true;
}

